#include <Cellerator/compiler/lto/implement_profile_environment_merge_v1.hh>
#include <map>
namespace cellerator::compiler::lto::v1 {
profile_merge_status_v1 merge_profile_environments_v1(const std::vector<std::vector<merge_profile_state_v1>>&es,std::size_t limit,merged_profile_environment_v1*r)noexcept{if(!r)return profile_merge_status_v1::invalid_state;r->states.clear();r->diagnostics.clear();std::map<std::pair<std::uint64_t,std::uint64_t>,std::size_t>seen;for(const auto&e:es)for(const auto&s:e){if(!(s.identity.high||s.identity.low)||!(s.evidence.high||s.evidence.low)||s.name.empty()||s.biological_semantics.empty()||!s.revision)return profile_merge_status_v1::invalid_state;auto k=std::make_pair(s.identity.high,s.identity.low);auto it=seen.find(k);if(it==seen.end()){seen[k]=r->states.size();r->states.push_back(s);}else{auto&old=r->states[it->second];if(old.biological_semantics!=s.biological_semantics){r->diagnostics.push_back("conflicting biological semantics for "+s.name);return profile_merge_status_v1::semantic_conflict;}if(s.revision>old.revision)old=s;}}if(r->states.size()>limit)return profile_merge_status_v1::too_many_alternatives;return profile_merge_status_v1::valid;}
}
